package ru.artem.beforethefall.resourcepack;
import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.player.PlayerJoinEvent;import org.bukkit.scheduler.BukkitRunnable;import ru.artem.beforethefall.BeforeTheFallPlugin;import java.io.InputStream;import java.nio.file.Files;import java.nio.file.Path;import java.security.MessageDigest;
public final class ResourcePackManager implements Listener{
 private final BeforeTheFallPlugin plugin;private byte[] hash;
 public ResourcePackManager(BeforeTheFallPlugin p){plugin=p;try{Path dir=p.getDataFolder().toPath();Files.createDirectories(dir);Path file=dir.resolve("resourcepack.zip");if(!Files.exists(file))try(InputStream in=p.getResource("resourcepack.zip")){if(in==null)throw new IllegalStateException("resourcepack.zip missing in plugin JAR");Files.copy(in,file);}hash=MessageDigest.getInstance("SHA-1").digest(Files.readAllBytes(file));p.getLogger().info("Embedded resource pack extracted to "+file);}catch(Exception ex){p.getLogger().severe("Resource pack error: "+ex.getMessage());}}
 @EventHandler public void onJoin(PlayerJoinEvent e){String url=plugin.getConfig().getString("resource-pack.url","").trim();if(url.isEmpty()||hash==null)return;new BukkitRunnable(){public void run(){Player p=e.getPlayer();if(p.isOnline())p.setResourcePack(url,hash);}}.runTaskLater(plugin,40L);}
}